<script setup>
import { computed, ref, watch } from 'vue';
const props=defineProps({mode:{type:String,required:true},completado:{type:Boolean,default:false}});const emit=defineEmits(['hablar','practicar']);
const paso=ref(1),opcionId=ref(0),variante=ref(0),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const meta=computed(()=>({
  can:{icono:'👐',sobre:'HABILIDAD Y CORTESÍA',titulo:'Can y could',bajada:'Hablá de habilidades, pedí permiso o formulá pedidos con distinto tono.',tabs:['Elegí el tono','Tres usos','Reto can / could']},
  obligation:{icono:'🔒',sobre:'OBLIGACIÓN',titulo:'Must y have to',bajada:'Expresá una regla fuerte o una necesidad causada por la situación.',tabs:['Medidor de obligación','Origen de la regla','Reto de reglas']},
  should:{icono:'🧭',sobre:'CONSEJO',titulo:'Should',bajada:'Ofrecé una recomendación sin convertirla en una obligación.',tabs:['Consultorio cotidiano','Consejo vs. obligación','Reto de consejos']},
  would:{icono:'☕',sobre:'DESEO CORTÉS',titulo:'Would like',bajada:'Pedí, ofrecé o expresá deseos de una manera amable y natural.',tabs:['Café de frases','Tres estructuras','Reto de cortesía']},
  imperative:{icono:'🪧',sobre:'INSTRUCCIÓN DIRECTA',titulo:'El imperativo',bajada:'Indicaciones claras con el verbo base; agregá please para suavizar.',tabs:['Director de acciones','Positivo y negativo','Reto de instrucciones']},
}[props.mode]));
const datos={
  can:[{icono:'🛍️',accion:'help me with these bags',etiqueta:'ayudar con las bolsas'},{icono:'🪟',accion:'open the window',etiqueta:'abrir la ventana'},{icono:'📍',accion:'tell me the way',etiqueta:'indicar el camino'},{icono:'📷',accion:'take a photo of us',etiqueta:'tomar una foto'}],
  obligation:[{icono:'🚗',accion:'wear a seat belt',etiqueta:'usar cinturón'},{icono:'🪪',accion:'bring an ID',etiqueta:'llevar identificación'},{icono:'💊',accion:'take this medicine',etiqueta:'tomar la medicina'},{icono:'🏠',accion:'be home by ten',etiqueta:'llegar a casa a las diez'}],
  should:[{icono:'😴',accion:'go to bed earlier',etiqueta:'I am always tired.'},{icono:'🥤',accion:'drink some water',etiqueta:'I am very thirsty.'},{icono:'🧥',accion:'take a jacket',etiqueta:'It is cold outside.'},{icono:'🗺️',accion:'ask someone for directions',etiqueta:'I am lost.'}],
  would:[{icono:'☕',accion:'a cup of coffee',etiqueta:'café'},{icono:'🥣',accion:'some soup',etiqueta:'sopa'},{icono:'💧',accion:'some water',etiqueta:'agua'},{icono:'🍰',accion:'a piece of cake',etiqueta:'pastel'}],
  imperative:[{icono:'🪟',accion:'Open the window',etiqueta:'abrir la ventana'},{icono:'⬅️',accion:'Turn left',etiqueta:'girar a la izquierda'},{icono:'⏳',accion:'Wait here',etiqueta:'esperar aquí'},{icono:'🥄',accion:'Add some sugar',etiqueta:'agregar azúcar'}],
};
const opciones=computed(()=>datos[props.mode]),opcion=computed(()=>opciones.value[opcionId.value]);
const frase=computed(()=>{
  if(props.mode==='can')return `${variante.value?'Could':'Can'} you ${opcion.value.accion}, please?`;
  if(props.mode==='obligation')return `You ${variante.value?'have to':'must'} ${opcion.value.accion}.`;
  if(props.mode==='should')return variante.value?`Should I ${opcion.value.accion}?`:`You should ${opcion.value.accion}.`;
  if(props.mode==='would')return variante.value?`Would you like ${opcion.value.accion}?`:`I'd like ${opcion.value.accion}, please.`;
  return variante.value?`Don't ${opcion.value.accion.charAt(0).toLowerCase()+opcion.value.accion.slice(1)}.`:`${opcion.value.accion}, please.`;
});
const referencias=computed(()=>({
  can:[{i:'💪',t:'CAN',d:'habilidad actual',e:'I can swim.'},{i:'🙋',t:'CAN I…?',d:'pedir permiso',e:'Can I sit here?'},{i:'🤝',t:'COULD YOU…?',d:'pedido más cortés',e:'Could you help me?'}],
  obligation:[{i:'🔴',t:'MUST',d:'regla fuerte del hablante',e:'You must be careful.'},{i:'📋',t:'HAVE TO',d:'necesidad externa',e:'I have to leave at six.'},{i:'🟢',t:"DON'T HAVE TO",d:'no es necesario',e:"You don't have to come."}],
  should:[{i:'🧭',t:'SHOULD',d:'recomendación',e:'You should rest.'},{i:'🚫',t:"SHOULDN'T",d:'recomendación negativa',e:"You shouldn't worry."},{i:'❓',t:'SHOULD I…?',d:'pedir consejo',e:'Should I call her?'}],
  would:[{i:'🙋',t:"I'D LIKE",d:'expresar un deseo',e:"I'd like some tea."},{i:'🎁',t:'WOULD YOU LIKE…?',d:'ofrecer algo',e:'Would you like dessert?'},{i:'🗺️',t:"I'D LIKE TO",d:'deseo + acción',e:"I'd like to visit Oaxaca."}],
  imperative:[{i:'▶️',t:'VERBO BASE',d:'instrucción positiva',e:'Close the door.'},{i:'⛔',t:"DON'T + VERBO",d:'instrucción negativa',e:"Don't touch that."},{i:'🙂',t:'PLEASE',d:'suaviza el tono',e:'Please, sit down.'}],
}[props.mode]));
const retos=computed(()=>({
  can:[{i:'🏊',f:'She ___ swim very well.',r:'can',o:['can','could to','cans','is can'],a:'Can + verbo base expresa habilidad.'},{i:'🤝',f:'___ you help me, please?',r:'Could',o:['Must','Could','Should to','Are'],a:'Could hace el pedido más cortés.'},{i:'🙋',f:'___ I use this chair?',r:'Can',o:['Do','Can','Am','Have'],a:'Can I…? pide permiso.'}],
  obligation:[{i:'🚗',f:'You ___ wear a seat belt.',r:'must',o:['must','should to','are','can to'],a:'Must expresa una obligación fuerte.'},{i:'🚌',f:'I ___ take the 7 AM bus; it is the only one.',r:'have to',o:['must to','have to','should','am'],a:'La situación externa crea la necesidad.'},{i:'🎉',f:"You ___ bring food; we have enough.",r:"don't have to",o:["mustn't","don't have to","shouldn't to","haven't"],a:"Don't have to significa que no es necesario."}],
  should:[{i:'😴',f:'You look tired. You ___ rest.',r:'should',o:['must to','should','are','can to'],a:'Should ofrece una recomendación.'},{i:'🍬',f:'You ___ eat so much candy.',r:"shouldn't",o:["don't should","shouldn't",'must to','not should'],a:"Shouldn't recomienda evitar algo."},{i:'❓',f:'___ I call her now?',r:'Should',o:['Do','Should','Am','Have'],a:'Should I…? pide consejo.'}],
  would:[{i:'☕',f:'I ___ a cup of coffee, please.',r:'would like',o:['would like','like to','would liking','am like'],a:"I would like —o la contracción I'd like— es una petición cortés."},{i:'🍰',f:'___ you like some cake?',r:'Would',o:['Do','Are','Would','Have'],a:'Would you like…? ofrece algo.'},{i:'🏖️',f:"We'd like ___ the beach.",r:'to visit',o:['visit','visiting','to visit','visited'],a:"Would like + acción usa to + verbo."}],
  imperative:[{i:'🚪',f:'___ the door, please.',r:'Close',o:['You close','Closing','Close','To close'],a:'El imperativo empieza con el verbo base.'},{i:'⛔',f:'___ run near the pool.',r:"Don't",o:["Doesn't",'No','Not',"Don't"],a:"Don't + verbo forma el imperativo negativo."},{i:'⬅️',f:'___ left at the corner.',r:'Turn',o:['Turning','Turns','Turn','To turn'],a:'Usamos el verbo base sin sujeto.'}],
}[props.mode]));
const reto=computed(()=>retos.value[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.r);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.r)aciertos.value=new Set([...aciertos.value,retoIdx.value])}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.value.length;elegida.value=null}watch(()=>props.mode,()=>{paso.value=1;opcionId.value=0;variante.value=0;retoIdx.value=0;elegida.value=null;aciertos.value=new Set()});
</script>

<template><section class="modal" :class="`modal--${mode}`"><aside class="hero"><span>{{meta.icono}}</span><div><small>ADULTO ESTÁNDAR · {{meta.sobre}}</small><h2>{{meta.titulo}}</h2><p>{{meta.bajada}}</p></div><div class="tone"><b>{{mode==='imperative'?'DO':mode==='would'?'POLITE':'MODAL'}}</b><i>＋</i><span>BASE</span></div></aside><nav><button v-for="(tab,i) in meta.tabs" :key="tab" :class="{active:paso===i+1}" @click="paso=i+1"><b>0{{i+1}}</b><span>{{tab}}</span></button></nav>
<main v-if="paso===1"><header><small>{{meta.sobre}} 1</small><h3>{{meta.tabs[0]}}</h3><p>{{mode==='should'?'Elegí una situación y construí un consejo.':'Elegí una situación y ajustá el tono de la frase.'}}</p></header><div class="option-grid"><button v-for="(x,i) in opciones" :key="x.accion" :class="{active:opcionId===i}" @click="opcionId=i"><span>{{x.icono}}</span><b>{{x.etiqueta}}</b></button></div><div class="switcher"><button :class="{active:variante===0}" @click="variante=0">{{mode==='can'?'CAN':mode==='obligation'?'MUST':mode==='should'?'SHOULD':mode==='would'?"I'D LIKE":'DO'}}</button><i>↔</i><button :class="{active:variante===1}" @click="variante=1">{{mode==='can'?'COULD':mode==='obligation'?'HAVE TO':mode==='should'?'SHOULD I?':mode==='would'?'WOULD YOU LIKE':"DON'T"}}</button></div><article class="result"><span>{{opcion.icono}}</span><small>FRASE NATURAL</small><strong>{{frase}}</strong><button @click="escuchar(frase)">🔊 Escuchar</button></article></main>
<main v-else-if="paso===2"><header><small>{{meta.sobre}} 2</small><h3>{{meta.tabs[1]}}</h3><p>Compará intención, estructura y tono antes de elegir.</p></header><div class="reference-grid"><article v-for="x in referencias" :key="x.t"><span>{{x.i}}</span><small>{{x.d}}</small><b>{{x.t}}</b><button @click="escuchar(x.e)">{{x.e}} 🔊</button></article></div><aside class="note"><b>Regla común:</b> después de un modal usamos el verbo en forma base, sin <i>to</i> y sin <i>-s</i>. <span v-if="mode==='would'">La excepción aquí es <i>would like to + acción</i>.</span></aside></main>
<main v-else><header class="challenge-head"><div><small>{{meta.sobre}} · RETO</small><h3>{{meta.tabs[2]}}</h3><p>Leé la intención y elegí la forma que suena natural.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.i}}</span><button @click="escuchar(reto.f.replace('___',reto.r))">{{reto.f}} 🔊</button><div><button v-for="o in reto.o" :key="o" :class="{ok:elegida&&o===reto.r,bad:elegida===o&&o!==reto.r}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Tono correcto':'↻ Revisá la intención'}}</b> {{reto.a}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente situación →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>

<style scoped>
