;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.result>span{font-size:2.4rem}.result strong{font:italic 1.2rem Georgia}.result button,.reference-grid button{margin-top:.45rem;padding:.45rem .7rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff}.reference-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem}.reference-grid article{display:flex;flex-direction:column;align-items:center;padding:.8rem;border:1px solid var(--color-borde);border-radius:13px;text-align:center}.reference-grid article>span{font-size:1.8rem}.reference-grid article>b{color:var(--accent)}.reference-grid button{font:italic .75rem Georgia}.note{margin-top:.7rem;padding:.7rem;border-left:4px solid var(--accent);border-radius:8px;background:var(--soft);font-size:.75rem}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--soft);color:var(--accent)}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.challenge>span{font-size:2.7rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.1rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:var(--color-rojo);background:var(--color-rojo-suave)}.next{padding:.55rem .8rem!important;background:var(--accent)!important;color:#fff!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:650px){.hero{grid-template-columns:auto 1fr}.tone{grid-column:1/-1;justify-content:center}nav,.reference-grid,.challenge>div{grid-template-columns:1fr}.option-grid{grid-template-columns:1fr 1fr}}@media(max-width:400px){.option-grid{grid-template-columns:1fr}}
</style>
